# A server wrapping an existing internal ticketing API
@server.tool()
async def create_ticket(title: str, description: str) -> dict:
    # Translates an MCP tool call into a call against the existing REST API
    response = await internal_ticketing_api.post("/tickets", json={
        "title": title, "description": description
    })
    return response.json()

@server.tool()
async def send_email(to: str, subject: str, body: str) -> dict:
    if "@" not in to:
        raise ValueError("to must be a valid email address")
    return await email_api.send(to=to, subject=subject, body=body)

from mcp.server import Server

server = Server("weather-server")

@server.tool()
async def get_forecast(city: str) -> dict:
    """Get the current weather forecast for a city."""
    return await weather_api.fetch(city)

@server.tool()
async def look_up_customer(customer_id: str) -> dict:
    row = await db.fetch_one("select * from customers where id = %s", customer_id)
    if row is None:
        raise ValueError(f"no customer found with id {customer_id}")
    return dict(row)

@server.resource("customer://{customer_id}")
async def customer_record(customer_id: str) -> str:
    row = await db.fetch_one("select * from customers where id = %s", customer_id)
    return json.dumps(dict(row))
